using System;using System.Collections.Generic;using System.Linq;using System.Threading;using UnityEngine;using UnityEngine.Rendering;using Unity.Collections;using SpatialWallpaper.Sdk.Execution;
namespace SpatialWallpaper.Sdk.Native.Unity {
 // Renderer-owned asynchronous staging. No pixels leave Unity, no frame readback,
 // and no caller can obtain a candidate until all chunks and its GPU fence finish.
 public sealed class NativeDynamicResources:IDisposable {
  sealed class GpuQueue:IRetirementQueue {
   sealed class Entry {internal object Native,Retained;internal ResourceLease Lease;internal Action<object> Destroy;internal NativeGpuCompletion Fence;internal bool DestroyIssued;}
   readonly List<Entry> entries=new List<Entry>();readonly OwnedDomain owner;internal GpuQueue(OwnedDomain owner){this.owner=owner;}
   public int Pending=>entries.Count;
   public void RequireCapacity(int n){if(n<0||entries.Count+n>128)throw new InvalidOperationException("dynamic-retirement-capacity");}
   public void Retire(object native,ResourceLease lease,Action<object> destroy,object retained=null){RequireCapacity(1);entries.Add(new Entry{Native=native,Lease=lease,Destroy=destroy,Retained=retained,Fence=new NativeGpuCompletion(owner)});}
   internal void Step(){for(int i=entries.Count-1;i>=0;i--){var e=entries[i];if(!e.Fence.Passed)continue;if(!e.DestroyIssued){if(e.Native!=null)e.Destroy(e.Native);e.DestroyIssued=true;}if(e.Native is UnityEngine.Object value&&value)continue;e.Fence.Dispose();e.Lease.Dispose();entries.RemoveAt(i);GC.KeepAlive(e.Retained);}}
  }
  sealed class Upload {internal NativeUploadInbox.Work Work;internal OwnedHandle Handle;internal int Vertex,Index,Pixel;internal NativeGpuCompletion Fence;internal string Error;}
  readonly List<NativeGpuCompletion> deferredCompletions=new List<NativeGpuCompletion>();void RetainCompletion(Upload u){if(u.Fence!=null){deferredCompletions.Add(u.Fence);u.Fence=null;}}
  readonly OwnedDomain owner;readonly NativeUploadInbox inbox;readonly ResourceInventory inventory;readonly GpuQueue retirement;readonly Dictionary<long,Upload> active=new Dictionary<long,Upload>();readonly int thread;bool disposed;
  public static bool Supported=>NativeGpuCompletion.Supported;
  public NativeDynamicResources(OwnedDomain owner,long authorityEpoch=1,Action<UnityEngine.Object> destroy=null){if(!Supported)throw new InvalidOperationException("dynamic-gpu-fence-unavailable");this.owner=owner??throw new ArgumentNullException(nameof(owner));retirement=new GpuQueue(owner);thread=Thread.CurrentThread.ManagedThreadId;inbox=new NativeUploadInbox(owner.Instance,owner.Generation,authorityEpoch,owner.Ledger);inventory=new ResourceInventory(owner,retirement,value=>{if(destroy!=null)destroy((UnityEngine.Object)value);else UnityEngine.Object.Destroy((UnityEngine.Object)value);});}
  void ThreadCheck(){if(Thread.CurrentThread.ManagedThreadId!=thread)throw new InvalidOperationException("dynamic-resource-main-thread");}
  public long AuthorityEpoch=>inbox.AuthorityEpoch;
  public long BeginMesh(Guid session,uint generation,long epoch,int vertices,params int[] submeshIndices)=>inbox.Begin(session,generation,epoch,NativeUploadSpec.Mesh(vertices,submeshIndices));
  public long BeginTexture(Guid session,uint generation,long epoch,int width,int height)=>inbox.Begin(session,generation,epoch,NativeUploadSpec.Texture(width,height));
  public void Append(long token,long epoch,int offset,byte[] bytes)=>inbox.Append(token,epoch,offset,bytes);
  public void Seal(long token,long epoch)=>inbox.Seal(token,epoch);
  public void Cancel(long token,long epoch)=>inbox.Cancel(token,epoch);
  public void Revoke(long nextEpoch)=>inbox.Revoke(nextEpoch);
  public NativeUploadPhase State(long token)=>inbox.State(token);
  public string Error(long token){ThreadCheck();return active.TryGetValue(token,out var value)?value.Error:null;}
  public bool CanDisposeOwner{get{ThreadCheck();return disposed&&retirement.Pending==0&&deferredCompletions.Count==0;}}
  static MeshUpdateFlags Flags=>MeshUpdateFlags.DontRecalculateBounds|MeshUpdateFlags.DontValidateIndices;
  void Create(Upload upload){var s=upload.Work.Spec;if(s.Kind=="mesh")upload.Handle=inventory.Create("mesh",ResourceEstimates.Mesh(s.Vertices,s.Indices),born=>{var mesh=new Mesh{name="Owned dynamic mesh"};born(mesh);mesh.MarkDynamic();mesh.SetVertexBufferParams(s.Vertices,new VertexAttributeDescriptor(VertexAttribute.Position,VertexAttributeFormat.Float32,3),new VertexAttributeDescriptor(VertexAttribute.Normal,VertexAttributeFormat.Float32,3),new VertexAttributeDescriptor(VertexAttribute.Tangent,VertexAttributeFormat.Float32,4),new VertexAttributeDescriptor(VertexAttribute.TexCoord0,VertexAttributeFormat.Float32,2),new VertexAttributeDescriptor(VertexAttribute.TexCoord1,VertexAttributeFormat.Float32,2),new VertexAttributeDescriptor(VertexAttribute.Color,VertexAttributeFormat.Float32,4));mesh.SetIndexBufferParams(s.Indices,IndexFormat.UInt32);return mesh;});else upload.Handle=inventory.Create("texture",ResourceEstimates.Texture(s.Width,s.Height,4,1,1),born=>{var texture=new Texture2D(s.Width,s.Height,TextureFormat.RGBA32,false,true){name="Owned dynamic texture",wrapMode=TextureWrapMode.Clamp};born(texture);return texture;});inbox.Transition(upload.Work,NativeUploadPhase.Uploading);}
  void UploadMesh(Upload u){var w=u.Work;var s=w.Spec;var mesh=(Mesh)inventory.Native(u.Handle,"mesh");if(u.Vertex<s.Vertices){int count=Math.Min(s.Vertices-u.Vertex,NativeUploadInbox.ChunkLimit/72);var block=new NativeArray<float>(count*18,Allocator.Temp,NativeArrayOptions.UninitializedMemory);try{for(int i=0;i<count;i++){int at=(u.Vertex+i)*72;for(int k=0;k<10;k++)block[i*18+k]=BitConverter.ToSingle(w.Bytes,at+k*4);for(int k=0;k<4;k++)block[i*18+10+k]=BitConverter.ToSingle(w.Bytes,at+(14+k)*4);for(int k=0;k<4;k++)block[i*18+14+k]=BitConverter.ToSingle(w.Bytes,at+(10+k)*4);}mesh.SetVertexBufferData(block,0,u.Vertex*18,count*18,0,Flags);u.Vertex+=count;}finally{block.Dispose();}return;}
   if(u.Index<s.Indices){int count=Math.Min(s.Indices-u.Index,NativeUploadInbox.ChunkLimit/4);var block=new NativeArray<uint>(count,Allocator.Temp,NativeArrayOptions.UninitializedMemory);try{for(int i=0;i<count;i++)block[i]=BitConverter.ToUInt32(w.Bytes,s.Vertices*72+(u.Index+i)*4);mesh.SetIndexBufferData(block,0,u.Index,count,Flags);u.Index+=count;}finally{block.Dispose();}return;}
   var descriptors=new SubMeshDescriptor[s.SubmeshIndices.Count];int offset=0;for(int i=0;i<descriptors.Length;i++){descriptors[i]=new SubMeshDescriptor(offset,s.SubmeshIndices[i],MeshTopology.Triangles){firstVertex=0,vertexCount=s.Vertices};offset+=s.SubmeshIndices[i];}mesh.SetSubMeshes(descriptors,Flags);var b=w.Bounds;mesh.bounds=new Bounds(new Vector3((b[0]+b[3])*.5f,(b[1]+b[4])*.5f,(b[2]+b[5])*.5f),new Vector3(b[3]-b[0],b[4]-b[1],b[5]-b[2]));mesh.UploadMeshData(false);WaitGpu(u);
  }
  void UploadTexture(Upload u){var w=u.Work;var texture=(Texture2D)inventory.Native(u.Handle,"texture");if(u.Pixel<w.Spec.Bytes){int count=Math.Min(w.Spec.Bytes-u.Pixel,NativeUploadInbox.ChunkLimit);var raw=texture.GetRawTextureData<byte>();for(int i=0;i<count;i++)raw[u.Pixel+i]=w.Bytes[u.Pixel+i];u.Pixel+=count;return;}texture.Apply(false,false);WaitGpu(u);}
  void WaitGpu(Upload u){u.Fence=new NativeGpuCompletion(owner);inbox.Transition(u.Work,NativeUploadPhase.WaitingGpu);}
  // A Step performs at most one resource construction, 64 KiB fill, final upload,
  // or fence poll. Driver/API atomic calls have a byte cap, not a measured ms guarantee.
  public void Step(){ThreadCheck();for(int i=deferredCompletions.Count-1;i>=0;i--)if(deferredCompletions[i].Passed){deferredCompletions[i].Dispose();deferredCompletions.RemoveAt(i);}retirement.Step();foreach(var w in inbox.All()){if(inbox.Current(w)||w.Phase==NativeUploadPhase.Published)continue;if(active.TryGetValue(w.Id,out var canceled)){RetainCompletion(canceled);if(canceled.Handle!=null)inventory.Release(canceled.Handle);active.Remove(w.Id);}inbox.Forget(w);}if(disposed)return;var pending=inbox.TakeReady();if(pending!=null)active.Add(pending.Id,new Upload{Work=pending});var u=active.Values.FirstOrDefault(x=>x.Work.Phase!=NativeUploadPhase.Ready&&x.Work.Phase!=NativeUploadPhase.Published&&x.Work.Phase!=NativeUploadPhase.Failed);if(u==null)return;
   try{if(!inbox.Current(u.Work))return;if(u.Handle==null){Create(u);return;}if(u.Work.Phase==NativeUploadPhase.WaitingGpu){if(u.Fence.Passed&&inbox.Transition(u.Work,NativeUploadPhase.Ready)){u.Fence.Dispose();u.Fence=null;inbox.ReleaseStaging(u.Work);}return;}if(u.Work.Spec.Kind=="mesh")UploadMesh(u);else UploadTexture(u);}catch(Exception error){u.Error=error.GetType().Name+":"+error.Message;inbox.Transition(u.Work,NativeUploadPhase.Failed);if(u.Handle!=null){inventory.Release(u.Handle);u.Handle=null;}inbox.ReleaseStaging(u.Work);/* Failure is returned through State/Error, never a fabricated Ready. */}
  }
  public UnityEngine.Object RequireReady(long token){ThreadCheck();if(!active.TryGetValue(token,out var u)||u.Work.Phase!=NativeUploadPhase.Ready||!inbox.Current(u.Work))throw new InvalidOperationException("dynamic-resource-not-ready");return (UnityEngine.Object)inventory.Native(u.Handle,u.Work.Spec.Kind);}
  public void Publish(long token,Action<UnityEngine.Object> rebind){ThreadCheck();if(rebind==null||!active.TryGetValue(token,out var u))throw new ArgumentException("dynamic-resource-publication");var value=RequireReady(token);inbox.Publish(u.Work,()=>rebind(value));}
  public void Retire(long token,Action detach){ThreadCheck();if(detach==null||!active.TryGetValue(token,out var u)||u.Work.Phase!=NativeUploadPhase.Published)throw new InvalidOperationException("dynamic-resource-not-published");retirement.RequireCapacity(1);detach();inventory.Release(u.Handle);active.Remove(token);u.Work.Phase=NativeUploadPhase.Retired;inbox.Forget(u.Work);}
  // Published users must explicitly detach first; silently destroying bound assets is forbidden.
  public void Dispose(){ThreadCheck();if(disposed)return;if(active.Values.Any(x=>x.Work.Phase==NativeUploadPhase.Published))throw new InvalidOperationException("dynamic-resource-detach-before-dispose");inbox.Dispose();foreach(var u in active.Values){RetainCompletion(u);if(u.Handle!=null)inventory.Release(u.Handle);}active.Clear();foreach(var w in inbox.All())inbox.Forget(w);inventory.Dispose();disposed=true;}
 }
}
